  "seo-locales": "The current guide declares lang=\"en\"; no locale variants or hreflang map are supplied.",
  "seo-rendering": "No rendered DOM was supplied and no browser capture is authorized offline; raw HTML only.",
  "aio-entity-consistency": "No product/entity record beyond the owner's guide-status statement is supplied; the product name and the current entitlement value cannot be compared with an authoritative record.",
  "aio-retrievable-facts": "The entitlement sentence is present in raw HTML, but audience context and target AI surface are not supplied; retrieval is not observed.",
  "aeo-question-coverage": "No customer question set is supplied; none is invented.",
  "aeo-answer-context": "No customer question set is supplied; none is invented.",
  "aeo-answer-evidence": "No dated source for the current entitlement claim is supplied; see quality-claims.",
  "geo-observed-presence": "No AI response observations are supplied; visibility is unmeasured, not zero.",
  "geo-answer-accuracy": "No AI response observations are supplied.",
  "geo-cohort-validity": "No AI observation cohort or prompt set is supplied.",
  "portfolio-task-gaps": "No question set or demand evidence is supplied; no gap is asserted.",
  "portfolio-journey-links": "No link graph or audience context is supplied; whether the archive links to the current guide is unknown.",
};
for (const [ruleId, reason] of Object.entries(unknownsR)) review(R, ruleId, "unknown", reason, [rc]);

review(M, "seo-structured-data", "fail",
  `Page A's JSON-LD block is not valid JSON: a comma follows the last member ("name": "Cedar Library",) before the closing brace; strict parsing fails (${parseA.error}). The owner asks for correct machine-readable descriptions. Clean component: Page B's block parses, declares WebPage and its name equals the visible heading 'Export reference'. Neither page uses Product, FAQPage, review or rating markup. Rendered DOM and engine handling are not observed; rich-result eligibility was not requested or tested.`,
  [mc, "markup-schema-extraction", "markup-publisher-intent"]);
review(M, "portfolio-duplication", "pass",
